const listCockpitInputExpiredTransfers = `-- name: ListCockpitInputExpiredTransfers :many
WITH waiting AS MATERIALIZED (
 SELECT workspace_id,input_id,version_id,id,lease_token,session_expires_at AS due_at FROM cockpit_input_transfer
 WHERE workspace_deleted_at IS NULL AND finished_at IS NULL AND state='awaiting_bytes' AND next_attempt_at<now() AND session_expires_at<now()
 ORDER BY next_attempt_at,id LIMIT 25
), lost AS MATERIALIZED (
 SELECT workspace_id,input_id,version_id,id,lease_token,lease_expires_at AS due_at FROM cockpit_input_transfer
 WHERE workspace_deleted_at IS NULL AND finished_at IS NULL AND state='reading' AND content_hash IS NULL AND lease_expires_at<now()
 ORDER BY lease_expires_at,id LIMIT 25
)
SELECT workspace_id,input_id,version_id,id,lease_token FROM (SELECT workspace_id, input_id, version_id, id, lease_token, due_at FROM waiting UNION ALL SELECT workspace_id, input_id, version_id, id, lease_token, due_at FROM lost) candidates ORDER BY due_at,id LIMIT 25
`

type ListCockpitInputExpiredTransfersRow struct {
	WorkspaceID pgtype.UUID `json:"workspace_id"`
	InputID     pgtype.UUID `json:"input_id"`
	VersionID   pgtype.UUID `json:"version_id"`
	ID          pgtype.UUID `json:"id"`
	LeaseToken  pgtype.UUID `json:"lease_token"`
}

func (q *Queries) ListCockpitInputExpiredTransfers(ctx context.Context) ([]ListCockpitInputExpiredTransfersRow, error) {
	rows, err := q.db.Query(ctx, listCockpitInputExpiredTransfers)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListCockpitInputExpiredTransfersRow{}
	for rows.Next() {
		var i ListCockpitInputExpiredTransfersRow
		if err := rows.Scan(
			&i.WorkspaceID,
			&i.InputID,
			&i.VersionID,
			&i.ID,
			&i.LeaseToken,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

